import base64
import json
import os
from typing import Any, Dict, List, Optional

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


def _read_bytes(source: Any) -> bytes:
    if source is None:
        raise ValueError("No receipt input provided.")
    if isinstance(source, bytes):
        return source
    if isinstance(source, str):
        if os.path.exists(source):
            with open(source, "rb") as f:
                return f.read()
        return source.encode("utf-8")
    if hasattr(source, "read"):
        data = source.read()
        if isinstance(data, str):
            return data.encode("utf-8")
        return data
    raise TypeError(f"Unsupported input type: {type(source)!r}")


def _field_value(field: Any) -> Any:
    if field is None:
        return None
    if hasattr(field, "value"):
        return field.value
    return field


def _field_content(field: Any) -> Optional[str]:
    if field is None:
        return None
    if hasattr(field, "content") and field.content is not None:
        return field.content
    v = _field_value(field)
    if v is None:
        return None
    return str(v)


def _normalize_items(lines: Any) -> List[Dict[str, Any]]:
    items: List[Dict[str, Any]] = []
    if not lines:
        return items

    for line in lines:
        item: Dict[str, Any] = {}
        if hasattr(line, "value"):
            line_value = line.value
            if hasattr(line_value, "description"):
                item["description"] = _field_content(line_value.description)
            if hasattr(line_value, "amount"):
                item["amount"] = _field_content(line_value.amount)
            if hasattr(line_value, "product_code"):
                item["product_code"] = _field_content(line_value.product_code)
            if hasattr(line_value, "quantity"):
                item["quantity"] = _field_content(line_value.quantity)
            if hasattr(line_value, "unit_price"):
                item["unit_price"] = _field_content(line_value.unit_price)
        if hasattr(line, "content") and line.content:
            item.setdefault("description", line.content)
        if item:
            items.append(item)
    return items


def extract_receipt(receipt_input: Any, *, endpoint: Optional[str] = None, api_key: Optional[str] = None) -> Dict[str, Any]:
    endpoint = endpoint or os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    api_key = api_key or os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_KEY")

    if not endpoint or not api_key:
        raise ValueError(
            "Azure Document Intelligence credentials are required via AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and "
            "AZURE_DOCUMENT_INTELLIGENCE_KEY."
        )

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(api_key))
    document_bytes = _read_bytes(receipt_input)

    poller = client.begin_analyze_document(
        "prebuilt-receipt",
        body=document_bytes,
        content_type="application/octet-stream",
    )
    result = poller.result()

    merchant = None
    tax = None
    total = None
    items: List[Dict[str, Any]] = []

    docs = getattr(result, "documents", None) or []
    if docs:
        doc = docs[0]
        fields = getattr(doc, "fields", {}) or {}

        merchant = (
            _field_content(fields.get("MerchantName"))
            or _field_content(fields.get("Merchant"))
            or _field_content(fields.get("VendorName"))
        )
        tax = _field_content(fields.get("TotalTax"))
        total = _field_content(fields.get("Total"))
        items = _normalize_items(getattr(fields.get("Items"), "value", None) or _field_value(fields.get("Items")))

    if not items:
        fields = {}
        if docs:
            fields = getattr(docs[0], "fields", {}) or {}
        items_field = fields.get("Items")
        if items_field is not None and hasattr(items_field, "value"):
            items = _normalize_items(items_field.value)

    return {
        "merchant": merchant,
        "tax": tax,
        "total": total,
        "items": items,
    }
